// mirror Three.js PolyhedronGeometry subdivide (non-indexed)
const icosaIndices = [0,11,5, 0,5,1, 0,1,7, 0,7,10, 0,10,11,
  1,5,9, 5,11,4, 11,10,2, 10,7,6, 7,1,8,
  3,9,4, 3,4,2, 3,2,6, 3,6,8, 3,8,9,
  4,9,5, 2,4,11, 6,2,10, 8,6,7, 9,8,1];
const icosaVerts = [
  1,0,0, 0,1,0, -1,0,0, 0,-1,0, 0,0,1, 0,0,-1,
  0.894,0,0.447, 0.276,0.851,0.447, -0.724,0.526,0.447,
  -0.724,-0.526,0.447, 0.276,-0.851,0.447,
  0.724,0.526,-0.447, 0.724,-0.526,-0.447, -0.276,0.851,-0.447,
  -0.894,0,-0.447, -0.276,-0.851,-0.447
];
function count(detail) {
  const vertexBuffer = [];
  function pushVertex(v){ vertexBuffer.push(v.x,v.y,v.z); }
  function getVertexByIndex(index, vertex) {
    const stride = index * 3;
    vertex.x = icosaVerts[stride]; vertex.y = icosaVerts[stride+1]; vertex.z = icosaVerts[stride+2];
  }
  const a={x:0,y:0,z:0}, b={x:0,y:0,z:0}, c={x:0,y:0,z:0};
  function lerp(p,q,t){ return {x:p.x+(q.x-p.x)*t, y:p.y+(q.y-p.y)*t, z:p.z+(q.z-p.z)*t}; }
  function clone(p){ return {x:p.x,y:p.y,z:p.z}; }
  function subdivideFace(a,b,c,detail) {
    const cols = detail + 1;
    const v = [];
    for (let i=0;i<=cols;i++){
      v[i]=[];
      const aj = lerp(a,c,i/cols);
      const bj = lerp(b,c,i/cols);
      const rows = cols - i;
      for (let j=0;j<=rows;j++){
        if (j===0 && i===cols) v[i][j]=aj;
        else v[i][j]=lerp(aj,bj,j/rows);
      }
    }
    for (let i=0;i<cols;i++){
      for (let j=0;j<2*(cols-i)-1;j++){
        const k=Math.floor(j/2);
        if (j%2===0){ pushVertex(v[i][k+1]); pushVertex(v[i+1][k]); pushVertex(v[i][k]); }
        else { pushVertex(v[i][k+1]); pushVertex(v[i+1][k+1]); pushVertex(v[i+1][k]); }
      }
    }
  }
  for (let i=0;i<icosaIndices.length;i+=3){
    getVertexByIndex(icosaIndices[i],a);
    getVertexByIndex(icosaIndices[i+1],b);
    getVertexByIndex(icosaIndices[i+2],c);
    subdivideFace(a,b,c,detail);
  }
  return vertexBuffer.length/3;
}
for (const d of [0,1,2,3]) console.log('detail', d, 'position.count', count(d));
"

