  'docks',
  'aurora',
  'vats',
  'railyard',
  'pitts',
  'limelight',
  'deeps',
]

Q.DISTRICT_MAP_COLORS = [
  0x142d54,
  0x1e6b8a,
  0x2d4a9a,
  0x176b7a,
  0x4a5088,
  0x3a78b0,
  0x1a4480,
]

