if (state && state.blocks) {
    for (var i = 0; i < state.blocks.length; i++) {
        var block = state.blocks[i]
        if (block.district.id !== 'Docks') { continue }
        var pop = block.population
        if (pop <= 0) { continue }
        popSum += pop
        weighted += pop * (block.prosperity != null ? block.prosperity : base)
    }
}
Q.docks_prosperity = popSum > 0 ? Math.round(weighted / popSum * 100) / 100 : base

var gPoll = Number(Q.Docks_poll_G) || 0
var hPoll = Number(Q.Docks_poll_H) || 0
var crimeRaw = 12 - Q.docks_prosperity + gPoll * 0.025 + hPoll * 0.012
Q.docks_crime = Math.round(Math.max(1, Math.min(10, crimeRaw)) * 100) / 100

var parties = [
    { code: 1, seats: Number(Q.Docks_C) || 0 },
    { code: 2, seats: Number(Q.Docks_G) || 0 },
    { code: 3, seats: Number(Q.Docks_D) || 0 },
    { code: 4, seats: Number(Q.Docks_H) || 0 },
    { code: 5, seats: Number(Q.Docks_I) || 0 },
]
var maxSeats = -1
for (var p = 0; p < parties.length; p++) {
    if (parties[p].seats > maxSeats) { maxSeats = parties[p].seats }
}
var leaders = []
for (var q = 0; q < parties.length; q++) {
    if (parties[q].seats === maxSeats && maxSeats > 0) { leaders.push(parties[q]) }
}
Q.docks_dominant_party = leaders.length === 1 ? leaders[0].code : 0
!}

= The Docks

The Docks are a glittering cosmopolitian area completely unconstained by the petty poverty or insidious control of the city below.  Travellers zipping between the inner and outer solar system go ashore here to dabble in arts, fine dining and deluxe services.  Genetic surgeons far more professional and refined then the chop shop docs below custom tailor aestetics to fit the personalities and whims of their well heeled clientelle.  Flashy luxury sport spaceships flit around carelessly below the massive space liners and freighters looming above.

Anything people could desire is for sale here, including power over the lives of others.

Crime level: [+ docks_crime : crime +] ([+ docks_crime +])
Prosperity level: [+ docks_prosperity : prosperity +] ([+ docks_prosperity +])
Political Dominance: [+ docks_dominant_party : party +]

